package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.collection.factory.mapdb.MapDb3CollectionFactory;
import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.junit.jupiter.api.Test;

class LegacySemanticScopeTest {

	private static final SimpleValueFactory VALUES = SimpleValueFactory.getInstance();

	@Test
	void realSpillingSetDeduplicatesLanguageAliasesAndClosesOnExhaustion() {
		List<Statement> rows = new ArrayList<>();
		for (int index = 0; index < 4096; index++) {
			rows.add(statement(index, "en"));
			rows.add(statement(index, "EN"));
		}
		TrackingSource source = new TrackingSource(rows);
		TrackingFactory factory = new TrackingFactory();
		AtomicInteger closed = new AtomicInteger();
		LegacySemanticScope<Statement> scope = scope(source, factory);
		scope.onClose(closed::incrementAndGet);
		int count = 0;
		while (scope.hasNext()) {
			scope.next();
			count++;
		}
		assertThat(count).isEqualTo(4096);
		assertThat(factory.initialized).as("The actual MapDB spill must have been initialized").isTrue();
		assertThat(factory.closed).isTrue();
		assertThat(source.closed).isTrue();
		assertThat(closed).hasValue(1);
		scope.close();
		assertThat(closed).hasValue(1);
	}

	@Test
	void earlyCloseReleasesSpilledSetAndSource() {
		List<Statement> rows = new ArrayList<>();
		for (int index = 0; index < 4096; index++) {
			rows.add(statement(index, "en"));
		}
		TrackingSource source = new TrackingSource(rows);
		TrackingFactory factory = new TrackingFactory();
		LegacySemanticScope<Statement> scope = scope(source, factory);
		for (int index = 0; index < 2048; index++) {
			scope.next();
		}
		assertThat(factory.initialized).isTrue();
		scope.close();
		assertThat(factory.closed).isTrue();
		assertThat(source.closed).isTrue();
		assertThat(scope.hasNext()).isFalse();
	}

	@Test
	void iterationFailureClosesSourceAndCollectionFactory() {
		TrackingSource source = new TrackingSource(List.of(statement(1, "en")));
		TrackingFactory factory = new TrackingFactory();
		LegacySemanticScope<Statement> scope = scope(source, factory);
		scope.next();
		source.failure = new IllegalStateException("scan failed");
		assertThatThrownBy(scope::hasNext).isSameAs(source.failure);
		assertThat(factory.closed).isTrue();
		assertThat(source.closed).isTrue();
	}

	@Test
	void cleanupPreservesFirstFailureAndSuppressesLaterFailure() {
		TrackingSource source = new TrackingSource(List.of(statement(1, "en")));
		TrackingFactory factory = new TrackingFactory();
		LegacySemanticScope<Statement> scope = scope(source, factory);
		scope.next();
		source.closeFailure = new IllegalStateException("source close failed");
		factory.closeFailure = new IllegalArgumentException("collection close failed");
		AtomicInteger closed = new AtomicInteger();
		scope.onClose(closed::incrementAndGet);
		assertThatThrownBy(scope::close).isSameAs(source.closeFailure)
				.hasSuppressedException(factory.closeFailure);
		assertThat(source.closed).isTrue();
		assertThat(factory.closed).isTrue();
		assertThat(closed).hasValue(1);
	}

	@Test
	void ownerClosesEveryScopeAfterAReaderFailsToClose() {
		LegacySemanticScope.Owner owner = new LegacySemanticScope.Owner();
		List<TrackingSource> sources = new ArrayList<>();
		List<TrackingFactory> factories = new ArrayList<>();
		for (int index = 0; index < 3; index++) {
			TrackingSource source = new TrackingSource(List.of(statement(index, "en")));
			TrackingFactory factory = new TrackingFactory();
			LegacySemanticScope<Statement> scope = scope(source, factory);
			scope.next();
			source.closeFailure = new IllegalStateException("source close failed " + index);
			sources.add(source);
			factories.add(factory);
			owner.own(scope);
		}
		assertThatThrownBy(owner::close).isInstanceOf(IllegalStateException.class)
				.satisfies(failure -> assertThat(failure.getSuppressed()).hasSize(2));
		assertThat(sources).allSatisfy(source -> assertThat(source.closed).isTrue());
		assertThat(factories).allSatisfy(factory -> assertThat(factory.closed).isTrue());
		owner.close();
	}

	@Test
	void ownerImmediatelyClosesReadersRegisteredAfterDatasetClose() {
		LegacySemanticScope.Owner owner = new LegacySemanticScope.Owner();
		owner.close();
		TrackingSource source = new TrackingSource(List.of(statement(1, "en")));
		LegacySemanticScope<Statement> scope = scope(source, new TrackingFactory());
		owner.own(scope);
		assertThat(source.closed).isTrue();
		assertThat(scope.hasNext()).isFalse();
	}

	@Test
	void nonLanguageRowsDoNotAllocateSemanticCollections() {
		Statement row = VALUES.createStatement(VALUES.createIRI("urn:plain:s"), VALUES.createIRI("urn:plain:p"),
				VALUES.createLiteral("plain"));
		TrackingSource source = new TrackingSource(List.of(row));
		LegacySemanticScope<Statement> scope = new LegacySemanticScope<>(source, value -> true,
				LegacySemanticScope::containsLanguage, LegacySemanticScope::detached,
				() -> {
					throw new AssertionError("No language-bearing row needs a semantic set");
				});
		assertThat(scope.next()).isEqualTo(row);
		assertThat(scope.hasNext()).isFalse();
		assertThat(source.closed).isTrue();
	}

	private LegacySemanticScope<Statement> scope(TrackingSource source, TrackingFactory factory) {
		return new LegacySemanticScope<>(source, value -> true, LegacySemanticScope::containsLanguage,
				LegacySemanticScope::detached, () -> factory);
	}

	private Statement statement(int index, String language) {
		return VALUES.createStatement(VALUES.createIRI("urn:semantic:" + index), VALUES.createIRI("urn:semantic:p"),
				VALUES.createLiteral("label", language));
	}

	private static final class TrackingFactory extends MapDb3CollectionFactory {
		private boolean initialized;
		private boolean closed;
		private RuntimeException closeFailure;

		private TrackingFactory() {
			super(1024);
		}

		@Override
		protected void init() {
			super.init();
			initialized = true;
		}

		@Override
		public void close() {
			super.close();
			closed = true;
			if (closeFailure != null) {
				throw closeFailure;
			}
		}
	}

	private static final class TrackingSource implements CloseableIteration<Statement> {
		private final List<Statement> rows;
		private int index;
		private boolean closed;
		private RuntimeException failure;
		private RuntimeException closeFailure;

		private TrackingSource(List<Statement> rows) {
			this.rows = rows;
		}

		@Override
		public boolean hasNext() {
			if (failure != null) {
				throw failure;
			}
			return !closed && index < rows.size();
		}

		@Override
		public Statement next() {
			return rows.get(index++);
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public void close() {
			closed = true;
			if (closeFailure != null) {
				throw closeFailure;
			}
		}
	}
}
